import{_ as a,o as d,c as e,ag as n}from"./chunks/framework.BcZEdlUI.js";const c=JSON.parse('{"title":"AI 工作流","description":"SceneFab 从视频素材到第一人称解说成片的 AI 工作流。","frontmatter":{"title":"AI 工作流","description":"SceneFab 从视频素材到第一人称解说成片的 AI 工作流。"},"headers":[],"relativePath":"guide/ai-video-guide.md","filePath":"guide/ai-video-guide.md","lastUpdated":1781612722000}'),r={name:"guide/ai-video-guide.md"};function s(i,t,l,h,o,p){return d(),e("div",null,[...t[0]||(t[0]=[n(`<h1 id="ai-工作流" tabindex="-1">AI 工作流 <a class="header-anchor" href="#ai-工作流" aria-label="Permalink to &quot;AI 工作流&quot;">​</a></h1><p>SceneFab 的 AI 流程围绕“剧情理解”和“可发布成片”设计。每个阶段都生成下一阶段需要的结构化信息，避免只把视觉模型输出直接丢给脚本模型。</p><h2 id="总览" tabindex="-1">总览 <a class="header-anchor" href="#总览" aria-label="Permalink to &quot;总览&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>视频输入</span></span>
<span class="line"><span>  -&gt; 场景理解</span></span>
<span class="line"><span>  -&gt; 剧情图谱</span></span>
<span class="line"><span>  -&gt; 短剧桥段识别</span></span>
<span class="line"><span>  -&gt; 第一人称脚本生成</span></span>
<span class="line"><span>  -&gt; 质量评估与 Hook 改写</span></span>
<span class="line"><span>  -&gt; 配音长度校准</span></span>
<span class="line"><span>  -&gt; 字幕与视频装配</span></span>
<span class="line"><span>  -&gt; 平台导出</span></span></code></pre></div><h2 id="_1-场景理解" tabindex="-1">1. 场景理解 <a class="header-anchor" href="#_1-场景理解" aria-label="Permalink to &quot;1. 场景理解&quot;">​</a></h2><p>场景理解负责把原始视频转换为可描述、可排序的片段。</p><table tabindex="0"><thead><tr><th>输入</th><th>输出</th></tr></thead><tbody><tr><td>视频文件、抽帧间隔、最小场景长度</td><td>场景列表、描述、起止时间、视觉线索</td></tr></tbody></table><p>推荐把视觉理解结果当作“事实来源”，而不是直接当成解说稿。脚本阶段还需要结合人物关系、前情和平台时长。</p><h2 id="_2-剧情图谱" tabindex="-1">2. 剧情图谱 <a class="header-anchor" href="#_2-剧情图谱" aria-label="Permalink to &quot;2. 剧情图谱&quot;">​</a></h2><p>剧情图谱用于解决长视频和短剧连续集常见的上下文断裂问题。</p><table tabindex="0"><thead><tr><th>信息</th><th>用途</th></tr></thead><tbody><tr><td>角色</td><td>防止人物称呼混乱</td></tr><tr><td>关键事件</td><td>帮助脚本按因果顺序叙述</td></tr><tr><td>冲突关系</td><td>决定第一人称情绪和立场</td></tr><tr><td>前情摘要</td><td>避免重复解释上一集内容</td></tr></tbody></table><h2 id="_3-短剧桥段识别" tabindex="-1">3. 短剧桥段识别 <a class="header-anchor" href="#_3-短剧桥段识别" aria-label="Permalink to &quot;3. 短剧桥段识别&quot;">​</a></h2><p>短剧解说需要高密度桥段。SceneFab 优先识别以下类型：</p><table tabindex="0"><thead><tr><th>桥段</th><th>典型用途</th></tr></thead><tbody><tr><td>身份揭露</td><td>开头或中段制造认知差</td></tr><tr><td>对峙冲突</td><td>推动人物关系变化</td></tr><tr><td>打脸反转</td><td>强化爽点</td></tr><tr><td>救场</td><td>提升转折强度</td></tr><tr><td>背叛</td><td>制造情绪下坠</td></tr><tr><td>心动</td><td>支撑甜宠和爱情线</td></tr><tr><td>结尾悬念</td><td>提升下一集点击动机</td></tr></tbody></table><h2 id="_4-第一人称脚本生成" tabindex="-1">4. 第一人称脚本生成 <a class="header-anchor" href="#_4-第一人称脚本生成" aria-label="Permalink to &quot;4. 第一人称脚本生成&quot;">​</a></h2><p>脚本生成会把四类上下文合并：</p><table tabindex="0"><thead><tr><th>上下文</th><th>示例</th></tr></thead><tbody><tr><td>指令上下文</td><td>人设、风格、平台、目标时长</td></tr><tr><td>数据上下文</td><td>场景、剧情图谱、桥段</td></tr><tr><td>历史上下文</td><td>已讲过的角色和剧情点</td></tr><tr><td>工具上下文</td><td>Few-shot、桥段模板、评估反馈</td></tr></tbody></table><p>脚本结构建议：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Hook: 前 3 秒交代冲突、身份、危险或结果。</span></span>
<span class="line"><span>主体: 用“我”的视角解释动机和情绪。</span></span>
<span class="line"><span>反击: 放大桥段和爽点。</span></span>
<span class="line"><span>收束: 给出后果、反转或下一集钩子。</span></span></code></pre></div><h2 id="_5-质量评估" tabindex="-1">5. 质量评估 <a class="header-anchor" href="#_5-质量评估" aria-label="Permalink to &quot;5. 质量评估&quot;">​</a></h2><p>生成脚本后，系统按五个维度评估：</p><table tabindex="0"><thead><tr><th>维度</th><th>关注点</th></tr></thead><tbody><tr><td>Hook</td><td>是否能在前几秒留下观看理由</td></tr><tr><td>桥段</td><td>是否触发短剧关键桥段</td></tr><tr><td>一致性</td><td>人物、前情和当前剧情是否一致</td></tr><tr><td>平台适配</td><td>字数、语速和时长是否匹配平台</td></tr><tr><td>风格</td><td>是否符合目标语气和样例</td></tr></tbody></table><p>不达标时，反馈会进入下一轮脚本生成或 Hook 改写。</p><h2 id="_6-配音和字幕" tabindex="-1">6. 配音和字幕 <a class="header-anchor" href="#_6-配音和字幕" aria-label="Permalink to &quot;6. 配音和字幕&quot;">​</a></h2><p>配音不是最后一步，而是脚本长度校准的一部分。</p><table tabindex="0"><thead><tr><th>项目</th><th>标准</th></tr></thead><tbody><tr><td>语速</td><td>按平台和目标时长估算字数</td></tr><tr><td>字幕</td><td>单条不超过两行</td></tr><tr><td>同步</td><td>字幕与配音偏差目标小于 50ms</td></tr><tr><td>响度</td><td>配音稳定压过原声</td></tr></tbody></table><h2 id="_7-导出和复盘" tabindex="-1">7. 导出和复盘 <a class="header-anchor" href="#_7-导出和复盘" aria-label="Permalink to &quot;7. 导出和复盘&quot;">​</a></h2><p>导出阶段会把生产参数固化为可复盘产物：</p><table tabindex="0"><thead><tr><th>产物</th><th>用途</th></tr></thead><tbody><tr><td>MP4 成片</td><td>直接上传平台</td></tr><tr><td>剪映草稿</td><td>二次精剪</td></tr><tr><td>字幕文件</td><td>审稿、修订和多平台复用</td></tr><tr><td>发布记录</td><td>标题、标签、平台、发布时间和表现复盘</td></tr></tbody></table><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/scene-fab/guide/first-person-narration-production.html">第一人称生产规范</a></li><li><a href="/scene-fab/guide/ai-configuration.html">AI 配置指南</a></li><li><a href="/scene-fab/guide/exporting.html">导出发布</a></li></ul>`,31)])])}const u=a(r,[["render",s]]);export{c as __pageData,u as default};
